public TreeNode<T> rotateRight(TreeNode<T> node) {
        TreeNode<T> parent = node.getParent();
        TreeNode<T> grandParent = node.getGrandParent();

        // Set the parent to be the new parent of the {@code node}
        parent.setParent(node);

        // Set the grandparent to be the parent of the {@code node}
        grandParent.setLeftChild(parent);

        // Set the node to be the left child of the grandparent
        grandParent.setRightChild(node);

        // Set the children of the {@code node}
        node.setParent(grandParent);
        node.setLeftChild(parent);
        node.setRightChild(null);

        return parent;
    }

