    // create an empty mapping
    HashMap<GraphEdge<V,E>, GraphEdge<V,E>> mapping = new HashMap<GraphEdge<V,E>, GraphEdge<V,E>>();

    // add the identity mapping from the original graph to itself
    for (GraphEdge<V,E> edge : graph.getEdges()) {
