    target.clear();

    // Add vertices to the left and right partition of the graph
    V left = new Vertex(), right = new Vertex();
    target.addVertex(left);
    target.addVertex(right);

    // Add edges between the vertices of the left partition and the right partition
    // with a weight of 1
    for (int i = 0; i < left.size(); i++) {
        for (int j = 0; j < right.size(); j++) {
            E edge = new Edge(left.get(i), right.get(j), 1);
            target.addEdge(edge);
        }
    }
}

