public static int writeDelimitedTo(OutputStream out, Object message, Schema schema, LinkedBuffer buffer) throws IOException {
    int size = computeSerializedSize(message, schema, buffer);
    out.write(size);
    size += schema.writeTo(buffer, out, message);
    out.write(0);
    return size;
}

public int writeDelimitedTo(OutputStream out) throws IOException {
    int serializedSize = writeDelimited(out, message, schema, buffer);
    CodedOutputStream codedOut = CodedOutputStream.newInstance(out, 0);
    codedOut.writeInt32NoTag(serializedSize);
    codedOut.write(codedOut);
    return serializedSize + codedOut.getTotalBytesWritten();
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    int totalBytesWritten = 0;

    int messageLength = CodedOutputStream.computeUInt32SizeNoTag(message.size());
    buffer.ensureCapacity(messageLength);

    CodedOutputStream.computeUInt32NoTag(messageLength, buffer);
    totalBytesWritten += messageLength;

    for (byte b : message.toByteArray()) {
        out.write(b);
        totalBytesWritten++;
    }

    return totalBytesWritten;
}

public static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    final byte[] serializedData = ProtobufUtils.toByteArray(message, schema);
    final int dataLength = serializedData.length;
    final byte[] serializedLength = Ints.toByteArray(dataLength);
    final byte[] dataWithLength = new byte[serializedLength.length + dataLength];
    System.arraycopy(serializedLength, 0, dataWithLength, 0, serializedLength.length);
    System.arraycopy(serializedData, 0, dataWithLength, serializedLength.length, dataLength);
    out.write(dataWithLength);
    return dataLength;
}

public int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    buffer.writeInt32(size, out, false);
    schema.writeTo(message, buffer.allocate(size), CodedOutputStream.computeInt32SizeNoTag(size), out);
    return size;
}

