public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType instanceof ParameterizedType) {
        ParameterizedType parameterizedGenType = (ParameterizedType) genericType;
        Type[] genTypeArgs = parameterizedGenType.getActualTypeArguments();
        TypeVariable<?>[] targetTypeVars = targetType.getTypeParameters();
        if (genTypeArgs.length == targetTypeVars.length) {
            return resolveArguments(genTypeArgs, targetTypeVars);
        }
    }
    return null;
}

private static Class<?>[] resolveArguments(Type[] genTypeArgs, TypeVariable<?>[] targetTypeVars) {
    if (genTypeArgs.length == targetTypeVars.length) {
        Class<?>[] resolvedArgs = new Class<?>[genTypeArgs.length];
        for (int i = 0; i < genTypeArgs.length; i++) {
            resolvedArgs[i] = resolveTypeVariable(genTypeArgs[i], targetTypeVars[i]);
        }
        return resolvedArgs;
    }
    return null;
}

private static Class<?> resolveTypeVariable(Type type, TypeVariable<?> typeVariable) {
    if (type instanceof Class) {
        return (Class<?>) type;
    } else {
        ParameterizedType paramType = (ParameterizedType) type;
        TypeVariable<?>[] typeVars = paramType.getTypeParameters();
        for (int i = 0; i < typeVars.length; i++) {
            TypeVariable<?> typeVar = typeVars[i];
            if (typeVar.getName().equals(typeVariable.getName()) && typeVar.getBounds().length > 0) {
                return resolveTypeVariable(typeVar.getBounds()[0], typeVariable);
            }
        }
    }
    return null;
}

public Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
		// Check if genericType is parameterized
		if (genericType instanceof ParameterizedType) {
			// Cast to ParameterizedType
			ParameterizedType parameterizedType = (ParameterizedType) genericType;
			// Get the type variables of the parameterized type
			TypeVariable<?>[] typeVariables = parameterizedType.getActualTypeArguments();
			// Check if targetType is assignable from the first type variable
			if (isAssignableFrom(typeVariables[0], targetType)) {
				// If so, get the raw type of the first type variable
				return getRawType(typeVariables[0]);
			}
		}
		// Return null if arguments cannot be resolved
		return null;
	}

public static Class[] resolveArguments(Type genericType, Class targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();
    TypeVariable[] typeVariables = targetType.getTypeParameters();
    if (typeArguments.length != typeVariables.length) {
        return null;
    }
    Map<TypeVariable, Type> typeVariableMap = new HashMap<>();
    for (int i = 0; i < typeArguments.length; i++) {
        TypeVariable typeVariable = typeVariables[i];
        Type typeArgument = typeArguments[i];
        typeVariableMap.put(typeVariable, typeArgument);
    }
    Class[] arguments = new Class[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        Type typeArgument = typeArguments[i];
        if (typeArgument instanceof Class) {
            arguments[i] = (Class) typeArgument;
        } else {
            TypeVariable typeVariable = (TypeVariable) typeArgument;
            arguments[i] = typeVariableMap.get(typeVariable);
        }
    }
    return arguments;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the genericType is not parameterized
    if (genericType.getTypeParameters().length == 0) {
        return null;
    }

    // Get the type variable mappings for the target type
    Map<TypeVariable<Type>, Type> variableMappings = new HashMap<>();
    resolveVariableMappings(targetType, variableMappings);

    // Resolve the arguments for the generic type
    Class<?>[] arguments = new Class[genericType.getTypeParameters().length];
    for (int i = 0; i < genericType.getTypeParameters().length; i++) {
        TypeVariable<Type> variable = genericType.getTypeParameters()[i];
        Type resolvedType = variableMappings.get(variable);
        if (resolvedType == null) {
            return null;
        }
        arguments[i] = (Class<?>) resolvedType;
    }

    return arguments;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
     if (!(genericType instanceof ParameterizedType)) {
         return null;
     }
     ParameterizedType parameterizedType = (ParameterizedType) genericType;
     Type[] typeArguments = parameterizedType.getActualTypeArguments();
     if (typeArguments == null || typeArguments.length == 0) {
         return null;
     }
     Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
     for (int i = 0; i < typeArguments.length; i++) {
         Type typeArgument = typeArguments[i];
         if (typeArgument instanceof Class) {
             resolvedArguments[i] = (Class<?>) typeArgument;
         } else if (typeArgument instanceof ParameterizedType) {
             resolvedArguments[i] = (Class<?>) ((ParameterizedType) typeArgument).getRawType();
         } else if (typeArgument instanceof TypeVariable) {
             TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument;
             resolvedArguments[i] = resolveTypeVariable(typeVariable, targetType);
         } else {
             throw new IllegalArgumentException("Unable to resolve type argument: " + typeArgument);
         }
     }
     return resolvedArguments;
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
     Type[] bounds = typeVariable.getBounds();
     if (bounds.length == 0) {
         return Object.class;
     }
     Type bound = bounds[0];
     if (bound instanceof Class) {
         return (Class<?>) bound;
     } else if (bound instanceof ParameterizedType) {
         ParameterizedType parameterizedBound = (ParameterizedType) bound;
         return resolveTypeVariable(parameterizedBound, targetType);
     } else if (bound instanceof TypeVariable) {
         TypeVariable<?> boundVariable = (TypeVariable<?>) bound;
         return resolveTypeVariable(boundVariable, targetType);
     } else {
         throw new IllegalArgumentException("Unable to resolve type variable: " + bound);
     }
}

public void accept(final METRICS data){
  	// Get the value from the data and increment it with the existing value by 1
    long incrementedValue = getValueFromData(data) + 1;

    // If the incremented value is greater than 0, update the cache with the new value
    if (incrementedValue > 0) {
      boolean updated = updateCache(incrementedValue);
      if (!updated) {
        System.out.println("Failed to update cache");
      }
    }
  }

private long getValueFromData(METRICS data){
    long value = 0;
    // If the data is valid, get the value and return it
    if (data.isValid()) {
      value = data.getValue();
    }
    return value;
  }

private boolean updateCache(long incrementedValue){
    boolean updated = false;
    // If the cache is not null and the new value is different from the existing value, update the cache and return true
    if (cache != null) {
      boolean newValueDifferent = !incrementedValue.equals(cache.getValue());
      if (newValueDifferent) {
        cache.setValue(incrementedValue);
        updated = true;
      }
    }
    return updated;
  }

