public void accept(final METRICS data) {

    Map dataMap = (Map) data;

    // Merge with existing data
    for (Map.Entry<String, Object> entry : dataMap.entrySet()) {
        String key = entry.getKey();
        Object value = entry.getValue();

        // If the key already exists in the cache, merge the corresponding value
        if (this.cache.containsKey(key)) {
            Object currentValue = this.cache.get(key);

            if (currentValue instanceof Map) {
                // If the current value is a map, recursively merge the values
                this.mergeValues(currentValue, value);
            } else if (currentValue instanceof List) {
                // If the current value is a list, add the new value to the end of the list
                ((List) currentValue).add(value);
            } else {
                // Otherwise, replace the current value with the new value
                this.cache.put(key, value);
            }
        } else {
            // If the key doesn't exist, add a new entry to the cache
            this.cache.put(key, value);
        }
    }
}

