public Mappings diffStructure(String tableName, Mappings mappings) {
    Mappings result = new Mappings();

    // Get the existing mappings for the table
    Mappings existingMappings = getMappings(tableName);

    // Loop through the input mappings and compare with the existing mappings
    for (Mapping m : mappings) {
        String fieldName = m.getName();
		// Check if the field already exists in the existing mappings
        if (!existingMappings.containsKey(fieldName)) {
            // Add the field with name and type to the result mappings
            Mapping newMapping = new Mapping(fieldName, m.getType());
            result.put(fieldName, newMapping);
        }
    }

    return result;
}

public Map<String, Object> diffStructure(String tableName, Map<String, Object> mappings) {
  Map<String, Object> difference = new HashMap<>();

  for (Map.Entry<String, Object> field : mappings.entrySet()) {
    if (field.getValue() instanceof Map) {
      // This field is a nested structure
      Map<String, Object> nestedDiff = diffStructure(field.getKey(), (Map<?, ?>) field.getValue());
      if (!nestedDiff.isEmpty()) {
        difference.put(field.getKey(), nestedDiff);
      }
    } else if (!field.getKey().equalsIgnoreCase("_source")) {
      // This field is a leaf field
      difference.put(field.getKey(), field.getValue());
    }
  }

  return difference;
}

