private long readValue(int offset, int size, int boolean) {
    switch (boolean) {
        case Short.BYTES:
            return readShort(offset) & 0xFFFF;
        case Integer.BYTES:
            return readInt(offset);
        case Long.BYTES:
            return readLong(offset);
        default:
            throw new IllegalArgumentException("Invalid size: " + size);
    }
}

private short readShort(int offset) {
    ensureOffsetIsValid(offset, Short.BYTES);
    return (short) (bytes[offset] << 8 | bytes[offset + 1] & 0xFF);
}

private int readInt(int offset) {
    ensureOffsetIsValid(offset, Integer.BYTES);
    return (bytes[offset] << 24) | (bytes[offset + 1] << 16) | (bytes[offset + 2] << 8) | (bytes[offset + 3] & 0xFF);
}

private long readLong(int offset) {
    ensureOffsetIsValid(offset, Long.BYTES);
    return (((long) bytes[offset]) << 56) | (((long) bytes[offset + 1]) << 48) | (((long) bytes[offset + 2]) << 40) | (((long) bytes[offset + 3]) << 32) | (((long) bytes[offset + 4]) << 24) | (((long) bytes[offset + 5]) << 16) | (((long) bytes[offset + 6]) << 8) | (((long) bytes[offset + 7]) & 0xFF);
}

private void ensureOffsetIsValid(int offset, int size) {
    if (offset < 0 || offset + size > bytes.length) {
        throw new IllegalArgumentException("Offset is out of bounds: " + offset);
    }
}

