List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long duration = Math.min(end - start, FETCH_DATA_DURATION);
        timeRanges.add(new TimeRange(start, duration));
        start += duration;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
  List<TimeRange> timeRanges = new ArrayList<>();
  while (start < end) {
    timeRanges.add(new TimeRange(start, Math.min(end, start + FETCH_DATA_DURATION)));
    start += FETCH_DATA_DURATION;
  }
  return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {
  List<TimeRange> timeRanges = new ArrayList<>();
  long startOffset = start % FETCH_DATA_DURATION;
  long endOffset = end % FETCH_DATA_DURATION;
  long currentStart = start - startOffset;
  long currentEnd = Math.min(currentStart + FETCH_DATA_DURATION, end);
  while (currentStart < end) {
    timeRanges.add(new TimeRange(currentStart, currentEnd));
    currentStart = currentEnd;
    currentEnd += FETCH_DATA_DURATION;
  }
  if (endOffset > 0) {
    timeRanges.add(new TimeRange(currentStart, end));
  }
  return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
  if (start > FETCH_DATA_DURATION || end > FETCH_DATA_DURATION) {
    throw new IllegalArgumentException("start time or end time must be less than or equal to " + FETCH_DATA_DURATION);
  }
  List<TimeRange> timeRanges = new ArrayList<>();
  long currentStart = 0;
  long currentEnd = currentStart + FETCH_DATA_DURATION;
  while (currentStart <= end) {
    TimeRange timeRange = new TimeRange(currentStart, Math.min(currentEnd, end));
    timeRanges.add(timeRange);
    currentStart += FETCH_DATA_DURATION;
    currentEnd += FETCH_DATA_DURATION;
  }
  return timeRanges;
}

public List<TimeRange> buildTimeRanges(long start, long end) {

    if (start >= FETCH_DATA_DURATION || end >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("start and end time must be less than FETCH_DATA_DURATION");
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    long currentStart = start;
    long currentEnd = currentStart + FETCH_DATA_DURATION;
    while (currentEnd < end) {
        timeRanges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd;
        currentEnd = currentStart + FETCH_DATA_DURATION;
    }

    if (currentEnd > end) {
        timeRanges.add(new TimeRange(currentStart, end));
    }

    return timeRanges;
}

