public static long compressTimeBucket(long timeBucket, int dayStep) {
    long compressedBucket = timeBucket;
    long datePart = compressedBucket / 1000000;
    long timePart = compressedBucket % 1000000;
    int refactoredTime = (timePart / 10000) + dayStep;
    if (refactoredTime >= 24) {
        refactoredTime = refactoredTime - 24;
    }
    compressedBucket = datePart * 1000000 + refactoredTime * 10000;
    return compressedBucket;
}

public long compressTimeBucket(long timeBucket, int dayStep) {
    return timeBucket - (timeBucket % (dayStep * 100)) + (timeBucket % dayStep);
}

private static long compressTimeBucket(long timeBucket, int dayStep) {
    return new Date(timeBucket).setSeconds(0).setMilliseconds(0).setMinutes(dayStep > 0 ? 60 * (dayStep / 10) + c(timeBucket % 10) * 5 : 0).setHours(dayStep > 0 ? dayStep / 10 : 0).setDate(dayStep > 0 ? d(timeBucket) + c(timeBucket % 10) - 7 : d(timeBucket)).getTime();
}

private static int d(long timeBucket) {
    return (int)((timeBucket % 1000000000) / 10000);
}

private static int c(long timeBucket) {
    return (int)(timeBucket % 10);
}

static long compressTimeBucket(long timeBucket, int dayStep) {
  // Check if the dayStep is valid
  if (dayStep < 1 || dayStep > 31) {
    throw new IllegalArgumentException("Invalid dayStep value: " + dayStep);
  }

  // Check if the timeBucket is valid
  if (timeBucket < 0 || timeBucket > 1000000000) {
    throw new IllegalArgumentException("Invalid timeBucket value: " + timeBucket);
  }

  // Calculate the new timeBucket
  long newTimeBucket = timeBucket / dayStep * dayStep;

  // Return the new timeBucket
  return newTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
  return timeBucket - (timeBucket % (dayStep * 100) + (timeBucket % 100 >= dayStep ? dayStep * 100 : 0));
}

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int utf8Size = 0;
    for (int i = index; i < len; i++) {
      int codepoint = str.charAt(i);
      if (codepoint <= 0x7F) {
        utf8Size += 1;
      } else if (codepoint <= 0x7FF) {
        utf8Size += 2;
      } else if (Character.isHighSurrogate(codepoint)) {
        utf8Size += 4;
        i++;
      } else {
        utf8Size += 3;
      }
    }
    return utf8Size;
  }

public int computeUTF8Size(final CharSequence str, int index, int len) {
	int size = 0;
	int oldIndex = index;
	while (index < len) {
		int ch = str.charAt(index);
		if (Character.isHighSurrogate(ch)) {
			int ch2 = str.charAt(index + 1);
			if (Character.isHighSurrogate(ch2)) {
				throw new IllegalArgumentException("High surrogate follows another high surrogate at index " + index +" (" + ch + ")");
			}
			++size;
			++index;
		} else if (Character.isLowSurrogate(ch)) {
			throw new IllegalArgumentException("Low surrogate at index " + index + "(" + ch + ")");
		}
		++index;
	}
	return size + index - oldIndex;
}

public int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int utf8Size = 0;
    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            utf8Size++;
        } else if (ch <= 0x7FF) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            utf8Size += 4;
        } else {
            utf8Size += 3;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    for (int i = 0; i < len; ) {
        final int ch = str.charAt(index + i);
        if (ch <= 0x7FF) {
            size += 2;
            i++;
        } else if (ch <= 0xFFFF) {
            size += 3;
            i++;
        } else if (Character.isSurrogate(ch)) {
            size += 4;
            i += 2;
        } else {
            size += 3;
            i++;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
  return str.charAt(index) >= 0x80 ? str.length() : index;
