public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null || byteLength == 0) {
        return this;
    }
    if (byteOffset > byteArrayValue.length - 1 || byteLength > byteArrayValue.length - byteOffset + 1) {
        throw new IndexOutOfBoundsException();
    }

    if (byteBuffer == null) {
        byteBuffer = ByteBuffer.allocate(byteLength + 1);
    } else if (byteBuffer.remaining() < byteLength) {
        int newSize = byteBuffer.capacity() * 2;
        while (newSize < byteLength + 1) {
            newSize *= 2;
        }
        byteBuffer.flip();
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(byteBuffer.array(), byteBuffer.position(), newBuffer, 0, byteBuffer.remaining());
        byteBuffer = ByteBuffer.wrap(newBuffer);
    }

    byteBuffer.position(byteBuffer.position() + byteOffset);
    byteBuffer.put(byteArrayValue, byteOffset, byteLength);
    byteBuffer.position(byteBuffer.position() + 1);

    return this;
}

