}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    final int strLen = str.length();
    final int[] intArr = new int[strLen];
    final int[] byteArr = new int[strLen * 3];

    for (int i = 0; i < strLen; i++) {
        intArr[i] = str.charAt(i);
    }

    for (int i = 0; i < strLen; i++) {
        int bytePos = i * 3;
        int c = intArr[i];
        byteArr[bytePos] = (byte) (c & 0xFF);
        byteArr[bytePos + 1] = (byte) ((c >> 8) & 0xFF);
        byteArr[bytePos + 2] = (byte) ((c >> 16) & 0xFF);
    }

    lb.write(byteArr, byteArr.length);
    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
  final int strLength = str.length();
  final int lbInitialSize = lb.size();
  lb.setSize(lbInitialSize + 1 + strLength);
  final int[] charBuffer = new int[strLength];
  for (int i = 0; i < strLength; i++) {
    charBuffer[i] = str.charAt(i);
  }

  int j = 0;
  for (int i = 0; i < strLength; i++) {
    final int codePoint = charBuffer[i];
    switch (Character.getType(codePoint)) {
      case Character.UPPERCASE_LETTER:
        fallthrough to lowercase case
      case Character.LOWERCASE_LETTER:
        fallthrough to digit 0 case
      case Character.DIGIT_0:
        fallthrough to digit 9 case
      case Character.DIGIT_9:
        fallthrough to non-ascii case
      case Character.NON_ASCII:
        lb.set(j++, (byte) codePoint);
        break;
      default:
        break;
    }
  }

  return lb;
}

