private static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }

    int strLength = str.length();
    int suffixLength = suffix.length();

    if (suffixLength > strLength) {
        return false;
    }

    int strEndIndex = strLength - suffixLength;
    String end = str.substring(strEndIndex, strLength);

    if (ignoreCase) {
        return end.equalsIgnoreCase(suffix);
    } else {
        return end.equals(suffix);
    }
}

private static boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return str == null && suffix == null;
    }

    if (ignoreCase) {
        return str.toLowerCase().endsWith(suffix.toLowerCase());
    } else {
        return str.endsWith(suffix);
    }
}

private boolean endsWith(String str, String suffix, boolean ignoreCase) {
    if (str == null || suffix == null) {
        return false;
    }

    if (ignoreCase) {
        str = str.toLowerCase();
        suffix = suffix.toLowerCase();
    }

    if (str.length() < suffix.length()) {
        return false;
    }

    return str.substring(str.length() - suffix.length()).equals(suffix);
}

public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
  List<PathSegmentImpl> pathSegments = new ArrayList<>();
  String[] segments = u.getPath().split("/");
  for (String segment : segments) {
    if (segment.isEmpty() && pathSegments.isEmpty()) {
      continue;
    }
    pathSegments.add(new PathSegmentImpl(segment, decode));
  }
  return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }
    int pos = 0;
    do {
        int delimPos = path.indexOf("/", pos);
        String segment;
        if (delimPos == -1) {
            segment = path.substring(pos);
        } else {
            segment = path.substring(pos, delimPos);
            pos = delimPos + 1;
        }
        if (decode) {
            segment = decodePathSegment(segment);
        }
        pathSegments.add(new PathSegmentImpl(segment));
    } while (pos < path.length());
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();
    if (decode) {
        path = URLDecoder.decode(path);
    }
    String[] pathSegmentsArr = path.split("/");
    for (int i = 0; i < pathSegments.length; i++) {
        pathSegments.add(new PathSegmentImpl(pathSegmentsArr[i]));
    }
    return pathSegments;
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getRawPath();
    if (path == null) {
        return pathSegments;
    }
    String[] pathComponents = path.split("/");
    for (String pathComponent : pathComponents) {
        if (pathComponent.startsWith("+")) {
            pathComponent.replaceAll("\\+", " ");
        } else if (!decode) {
            pathComponent = URLDecoder.decode(pathComponent, "UTF-8");
        }
        pathSegments.add(new PathSegmentImpl(pathComponent));
    }
    return pathSegments;
}

public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    if (u.getPath().startsWith("/")) {
        String path = u.getPath().substring(1);
        boolean hasMoreSegments = true;

        while (hasMoreSegments) {
            int nextSlash = path.indexOf("/");
            String segment = (nextSlash == -1) ? path : path.substring(0, nextSlash);
            pathSegments.add(new PathSegmentImpl(segment, decode));

            if (nextSlash != -1) {
                path = path.substring(nextSlash + 1);
            } else {
                hasMoreSegments = false;
            }
        }
    } else {
        pathSegments.add(new PathSegmentImpl(u.getPath(), decode));
    }

    return pathSegments;
}

