public long readRawVarint64() throws IOException {
    var temp = new BitArray(64);
    var pos = 0;
    while (true) {
        var b = readByte();
        if (b < 0) {
            throw new IOException("Unexpected end of stream");
        }
        temp.set(pos, b & 1);
        if ((b & 128) == 0) {
            break;
        }
        pos++;
    }
    return temp.toLong();
}

