private void putAbstractTypes(int start, int end) {
  for (int i = start; i < end; i++) {
    VerificationTypeInfo type = currentFrame[i];
    if (type.isValid()) {
      stackMapTableEntries.add(type.getVerificationTypeInfo());
    }
  }
}

private void putAbstractTypes(int start, int end) {
    StackMapTableEntry[] stackMapTableEntries = new StackMapTableEntry[end - start];
    for (int i = start; i < end; i++) {
        StackMapTableEntry entry = new StackMapTableEntry();
        entry.setIndicator(0);
        entry.setTypeOrNull(currentFrame[i]);
        stackMapTableEntries[i - start] = entry;
    }
}

private void putAbstractTypes(final int start, final int end) {
        // Put a STACK_FULL_FRAME entry in the StackMapTable
        final int frameType = JVM_OPCODES.STACK_FULL_FRAME;
        stackMapTableEntries.add(frameType);

        // Put the local and stack item counts in the frame
        final int localCount = end - start;
        stackMapTableEntries.add(localCount);

        // Put the abstract types of the current frame in the StackMapTable
        for (int i = start; i < end; i++) {
            final int abstractType = currentFrame.get(i).getAbstractType();
            stackMapTableEntries.add(abstractType);
        }
    }

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        switch (currentFrame.get(i).getTag()) {
            case AbstractTypeTag.ABSTRACTTYPE_TOP:
                stackMapTableEntries.add(new TopStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_INTEGER:
                stackMapTableEntries.add(new IntegerStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_FLOAT:
                stackMapTableEntries.add(new FloatStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_ITEM_NULL:
                stackMapTableEntries.add(new NullStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_ITEM_UNINIT:
                stackMapTableEntries.add(new UninitStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_ITEM_UNINIT_THIS:
                stackMapTableEntries.add(new UninitThisStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_REFERENCE:
                ReferenceType referenceType = currentFrame.get(i).getReferenceType();
                stackMapTableEntries.add(new ReferenceStackMapFrame(referenceType));
                break;
            case AbstractTypeTag.ABSTRACTTYPE_LONG:
                stackMapTableEntries.add(new LongStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_DOUBLE:
                stackMapTableEntries.add(new DoubleStackMapFrame());
                break;
            case AbstractTypeTag.ABSTRACTTYPE_TOP_2:
                stackMapTableEntries.add(new Top2StackMapFrame());
                break;
        }
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        VerificationTypeInfo info = currentFrame[i].getVerificationTypeInfo();
        if (info instanceof VerificationTypeInfo.ObjectTypeInfo) {
            VerificationTypeInfo.ObjectTypeInfo objectInfo = (VerificationTypeInfo.ObjectTypeInfo) info;
            stackMapTableEntries.add(new VerificationTypeInfo.AbstractTypeInfo(objectInfo.getClassName(), objectInfo.getCpIndex()));
        } else {
            stackMapTableEntries.add(info);
        }
    }
}

