public static Character convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value instanceof Character) {
            return (Character) value;
        } else if (value instanceof Number) {
            return Character.valueOf((char) ((Number) value).intValue());
        } else if (value instanceof String) {
            return ((String) value).length() > 0 ? Character.valueOf(((String) value).charAt(0)) : null;
        } else {
            throw new Exception("Cannot convert " + value.getClass().getName() + " to " + type.getName());
        }
    } else {
        throw new Exception("Cannot convert " + value.getClass().getName() + " to " + type.getName());
    }
}

