public int nextPrime(int desiredCapacity){
    if(desiredCapacity < 0){
        throw new IllegalArgumentException("Desired capacity cannot be negative");
    } else if (desiredCapacity == 0){
        return 1;
    } else if (desiredCapacity < 1000){
        return desiredCapacity > 50 ? desiredCapacity : 50;
    } else {
        while (true){
            int candidate = nextPrime(desiredCapacity / 3) * 3 + 1;
            if (candidate > desiredCapacity || Math.abs(candidate - desiredCapacity) / (float)desiredCapacity > 0.11) {
                return candidate;
            }
        }
    }
}

method nextPrime(desiredCapacity: int): int
  // Calculate the nearest prime number
  var prime = desiredCapacity * 2 + 1

  // Loop until the prime number meets the condition
  while (!isPrime(prime))
    prime += 2

  return prime
}

