public static String trimTrailingWhitespace(String str){
  StringBuilder sb = new StringBuilder(str);
  for(int i=sb.length()-1; i>=0; i--){
    if(Character.isWhitespace(sb.charAt(i))){
      sb.deleteCharAt(i);
    }else{
      break;
    }
  }
  return sb.toString();
}

public static String trimTrailingWhitespace(String str) {
    // Check if the string is null or empty
    if (str == null || str.length() == 0) {
        return str;
    }
    // Loop through the string from the end and check if the character is whitespace
    for (int i = str.length() - 1; i >= 0; i--) {
        if (!Character.isWhitespace(str.charAt(i))) {
            // Return the substring up to the first non-whitespace character
            return str.substring(0, i + 1);
        }
    }
    // If all characters are whitespace, return an empty string
    return "";
}

public static String trimTrailingWhitespace(String str) {
    int len = str.length();
    if (len == 0) {
        return str;
    }

    int index = 0;
    while (Character.isWhitespace(str.charAt(len - 1 - index))) {
        index++;
    }

    return str.substring(0, len - index);
}

