		if (c == '\\' && i < str.length() - 1) {
			char nextChar = str.charAt(i + 1);
			switch (nextChar) {
				case 'n': sb.append('\n'); break;
				case 'r': sb.append('\r'); break;
				case 't': sb.append('\t'); break;
				case '\\': sb.append('\\'); break;
				default:
					if (nextChar >= '0' && nextChar <= '7') {
						int value = nextChar - '0';
						if (i < str.length() - 2 && str.charAt(i + 2) >= '0' && str.charAt(i + 2) <= '7') {
							value = (value * 8) + (str.charAt(i + 2) - '0');
							i++;
							if (value <= 255) {
								sb.append((char)value);
								break;
							}
						}
					}
					sb.append(c); // Unknown escape sequence, append the \ and following character
					break;
			}
			i++;
		} else {
