public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    int len = str.length();
    if (len == 0) {
        return str;
    }
    int pos = 0;
    while (pos < len) {
        char c = str.charAt(pos++);
        if (c == '\\') {
            c = str.charAt(pos++);
            switch (c) {
                case '\\': return str.substring(0, pos);
                case 'n': return str.substring(0, pos).replace("\\n", "\n");
                case 'r': return str.substring(0, pos).replace("\\r", "\r");
                case 't': return str.substring(0, pos).replace("\\t", "\t");
                case 'u': return str.substring(0, pos).replace("\\u", "\u");
                case '\'': return str.substring(0, pos).replace("\\\'", "\'");
                case '\"': return str.substring(0, pos).replace("\\\"", "\"");
                default: return str.substring(0, pos).replace("\\" + c.toString(), c.toString());
            }
        }
    }
    return str;
}

