		String[] constantPool = classFileBuffer.getConstantPool();
		if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= constantPool.length) {
			throw new IllegalArgumentException("constantPoolIndex must be between 0 and " + (constantPool.length - 1));
		}

		String constant = constantPool[constantPoolEntryIndex];
		if (constant != null) {
			return constant;
		}

		int utfLength = classFileBuffer.getU1();
		if (utfLength > charBuffer.length) {
			throw new IllegalArgumentException("charBuffer is too small");
		}

		for (int i = 0; i < utfLength; i++) {
			charBuffer[i] = (char) classFileBuffer.getU2();
		}

		constantPool[constantPoolEntryIndex] = new String(charBuffer, 0, utfLength);

		return constantPool[constantPoolEntryIndex];
	}

