  }
}

private void check(String modelName) throws IllegalStateException {
  if (!isEntityWithShardingKey(modelName)) {
    return;
  }
  int[] indices = getShardingKeyIndices(modelName);
  if (indices.length <= 1) {
    return;
  }
  int prevIndex = indices[0];
  for (int i = 1; i < indices.length; i++) {
    if (indices[i] != prevIndex + 1) {
      throw new IllegalStateException("Sharding key indices must be continuous");
    }
    prevIndex = indices[i];
  }
}

private void check(String modelName) throws IllegalStateException {
    Set<String> indices = getShardingKeyIndices(modelName);
    if (indices.size() == 1) {
        return;
    }
    int currentIndex = indices.first();
    for (String index : indices) {
        if (Integer.parseInt(index) != currentIndex + 1) {
            throw new IllegalStateException("Sharding key indices are not continuous");
        }
        currentIndex++;
    }
}

