public static int addConstantNameAndType(final String name, final String descriptor) {
        int index = -1;
        if (name == null || descriptor == null) {
            return index;
        }
        for (int i = 1; i < constantPool.size(); i++) {
            Constant constant = constantPool.get(i);
            if (constant instanceof ConstantNameAndType) {
                ConstantNameAndType constantNameAndType = (ConstantNameAndType) constant;
                if (constantNameAndType.getName().equals(name) && constantNameAndType.getDescriptor().equals(descriptor)) {
                    index = i;
                    break;
                }
            }
        }
        if (index == -1) {
            ConstantNameAndType constantNameAndType = new ConstantNameAndType(name, descriptor);
            index = constantPool.add(constantNameAndType);
        }
        return index;
    }

public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    if (constantPool.containsKey(new Pair<>(name, descriptor))) {
        return constantPool.get(new Pair<>(name, descriptor));
    }

    // Add the new item to the constant pool
    int index = constantPool.size() + 1;
    constantPool.put(new Pair<>(name, descriptor), index);

    return index;
}

public int addConstantNameAndType(final String name,final String descriptor) {
    if (name == null || descriptor == null) {
        throw new NullPointerException();
    }
    int index = constantToString(name + descriptor);
    if (index < 0) {
        index = constantPool.size();
        constantPool.add(new ConstantNameAndType(name, descriptor));
    }
    return index;
}

public Symbol addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains an item similar to the given name and descriptor
    Symbol constant = constantPool.get(name + ":" + descriptor);
    if (constant != null) {
        return constant;
    }

    // If the constant pool does not contain a similar item, create a new one and add it to the pool
    constant = new Symbol(name, descriptor);
    constantPool.put(constant);

    return constant;
}

