private String unescapeId(String input) {
    String output = "";
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '\\') {
            i++;
            char escapedChar = input.charAt(i);
            switch (escapedChar) {
                case '"':
                    output += '\"';
                    break;
                case '\\':
                    output += '\\';
                    break;
                case 'b':
                    output += '\b';
                    break;
                case 'f':
                    output += '\f';
                    break;
                case 'n':
                    output += '\n';
                    break;
                case 'r':
                    output += '\r';
                    break;
                case 't':
                    output += '\t';
                    break;
                default:
                    output += escapedChar;
                    break;
            }
        } else {
            output += c;
        }
    }
    return output;
}

