            char c = input.charAt(i + 1);
            switch (c) {
                case 'n':
                    output.append("\n");
                    break;
                case 'r':
                    output.append("\r");
                    break;
                case 't':
                    output.append("\t");
                    break;
                case 'f':
                    output.append("\f");
                    break;
                case '\"':
                    output.append("\"");
                    break;
                case '\'':
                    output.append("'");
                    break;
                case '\\':
                    output.append("\\");
                    break;
                default:
                    output.append(c);
            }
            i++;
        } else {
            output.append(input.charAt(i));
        }
    }
    return output.toString();
}

