        for (int vertex : vertexSet) {
            labels.set(vertex, 0);
        }
        bucketsByLabel.get(minLabel).addAll(vertexSet);
        bucketsByLabel.get(i).clear();
        i++;
    }
    for (Set<Integer> vertexSet : bucketsByLabel) {
        for (int vertex : vertexSet) {
            labels.set(vertex, minLabel);
        }
    }
