private boolean unlink(ListNodeImpl<E> node) {
    if (node == null)
        return false;
    int index = list.indexOf(node.getValue());
    if (index == -1)
        return false;
    ListNodeImpl<E> previous = list.get(index - 1);
    ListNodeImpl<E> next = list.get(index + 1);
    if (previous == null)
        list.setFirst(next);
    else
        previous.setNext(next);
    if (next == null)
        list.setLast(previous);
    else
        next.setPrev(previous);
    list.remove(index);
    list.setSize(list.size() - 1);
    return true;
}

