private List<SequenceRange> buildSequenceRanges() {
	List<SequenceRange> sequenceRanges = new ArrayList<>();

	for (int i = 0; i < profiles.size() - 1; i++) {
		Profile currentProfile = profiles.get(i);
		Profile nextProfile = profiles.get(i + 1);
		if (currentProfile.getShortName().equalsIgnoreCase(nextProfile.getShortName())) {
			SequenceRange sequenceRange = new SequenceRange(currentProfile.getStartLocation(), nextProfile.getStartLocation());
			sequenceRanges.add(sequenceRange);
		}
	}

	return sequenceRanges;
}

private List<SequenceRange> buildSequenceRanges() {
		List<SequenceRange> sequenceRanges = new ArrayList<>();

		for (int i = 0; i < currentProfiles.size(); i++) {
			int currentProfileStart = currentProfiles.get(i).getStart();
			int currentProfileEnd = currentProfiles.get(i).getEnd();

			for (int j = 0; j < segmentSnapshot.size(); j++) {
				int snapshotStart = segmentSnapshot.get(j).getStart();
				int snapshotEnd = segmentSnapshot.get(j).getEnd();

				if (currentProfileStart >= snapshotStart && currentProfileEnd <= snapshotEnd) {
					sequenceRanges.add(new SequenceRange(currentProfileStart, currentProfileEnd));
				}
			}
		}

		return sequenceRanges;
	}

