        int b1 = BASE64_ENCODING[codePoints[i]];
        int b2 = BASE64_ENCODING[codePoints[i + 1]];
        int b3 = BASE64_ENCODING[codePoints[i + 2]];
        int b4 = BASE64_ENCODING[codePoints[i + 3]];
        builder.append((char) ((b1 << 2) | (b2 >> 4)));
