    for (Pair<Integer, Integer> neighbor : graph.getNeighbors(edge.getFirst())) {
      if (neighbor.getFirst() == edge.getSecond()) {
        separators.add(new Pair<>(neighbor.getFirst(), neighbor.getSecond()));
      }
    }
    result.add(new Pair<>(separators, edge));
  }
  return result;
}

