private void pop(final String descriptor) {
        int brackets = 0;
        int index = 0;
        while (index < descriptor.length()) {
            switch (descriptor.charAt(index)) {
                case '[':
                    brackets++;
                    break;
                case ']':
                    brackets--;
                    break;
                case '(':
                    if (brackets == 0) {
                        pop(descriptor.substring(index + 1, descriptor.length() - 1));
                        return;
                    }
                    break;
                default:
                    break;
            }
            index++;
        }
    }

private void pop(final String descriptor) {
    int stackSize = getStackSize();
    if (descriptor.charAt(0) == '(') {
        final String argTypes = descriptor.substring(1, descriptor.indexOf(')'));
        for (int i = 0; i < argTypes.length(); i++) {
            final String argType = argTypes.charAt(i);
            switch (argType) {
                case 'I':
                    popInt();
                    break;
                case 'J':
                    popLong();
                    break;
                case 'F':
                    popFloat();
                    break;
                case 'D':
                    popDouble();
                    break;
                case 'L':
                    popObject();
                    break;
                default:
                    throw new IllegalArgumentException("Unknown argument type: " + argType);
            }
        }
    } else {
        final String argType = descriptor.charAt(0);
        switch (argType) {
            case 'I':
                popInt();
                break;
            case 'J':
                popLong();
                break;
            case 'F':
                popFloat();
                break;
            case 'D':
                popDouble();
                break;
            case 'L':
                popObject();
                break;
            default:
                throw new IllegalArgumentException("Unknown argument type: " + argType);
        }
    }
    if (stackSize != getStackSize()) {
        throw new IllegalStateException("Frame stack size does not match");
    }
}

