public static String applyRelativePath(String path, String relativePath) {
    String[] pathTokens = path.split("/");
    String[] relativePathTokens = relativePath.split("/");

    for (int i = 0; i < relativePathTokens.length; i++) {
        if (relativePathTokens[i].equals("..")) {
            pathTokens.popLast();
        } else if (!relativePathTokens[i].equals(".")) {
            pathTokens.push(relativePathTokens[i]);
        }
    }

    return String.join("/", pathTokens);
}

public String applyRelativePath(String path, String relativePath) {
  if (path == null || relativePath == null) {
    return null;
  }

  String[] pathParts = path.split("/");
  String[] relativePathParts = relativePath.split("/");

  for (int i = 0; i < relativePathParts.length; i++) {
    String part = relativePathParts[i];
    if (part.equals("..")) {
      pathParts = Arrays.copyOfRange(pathParts, 0, pathParts.length - 1);
    } else if (!part.equals(".")) {
      pathParts = Arrays.copyOf(pathParts, pathParts.length + 1);
      pathParts[pathParts.length - 1] = part;
    }
  }

  return String.join("/", pathParts);
}

