public static int indexOfExtension(String filename) {
  if (filename == null) {
    return -1;
  }

  int lastUnixSeparatorIndex = indexOfLastSeparator(filename);
  int extensionIndex = filename.lastIndexOf(".");

  if (extensionIndex > -1) {
    if (extensionIndex < lastUnixSeparatorIndex) {
      return -1;
    } else {
      return extensionIndex;
    }
  } else {
    return -1;
  }
}

public int indexOfLastExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    int extensionIndex = filename.length();
    while (true) {
        int nextSeparatorIndex = indexOfLastSeparator(filename);
        if (nextSeparatorIndex == -1 || nextSeparatorIndex >= extensionIndex) {
            break;
        }
        extensionIndex = nextSeparatorIndex;
    }
    return extensionIndex;
}

