public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<ThreadSnapshot>();
    try (InputStream fis = new FileInputStream(file);
         BufferedReader br = new BufferedReader(new InputStreamReader(fis))) {
      String line;
      while ((line = br.readLine())) {
        for (ProfileAnalyzeTimeRange range : timeRanges) {
          if (line.contains(range.startTime) && line.contains(range.endTime)) {
            String[] parts = line.split(",");
            ThreadSnapshot snapshot = new ThreadSnapshot(Long.parseLong(parts[0]), Long.parseLong(parts[1]), Long.parseLong(parts[2]));
            snapshots.add(snapshot);
          }
        }
      }
    } catch (NumberFormatException ex) {
      throw new IOException("Invalid input format", ex);
    }
    return snapshots;
  }

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (!line.isEmpty()) {
                String[] tokens = line.split(",");
                if (tokens.length == 4) {
                    long startTime = Long.parseLong(tokens[0].trim());
                    long endTime = Long.parseLong(tokens[1].trim());
                    int threadId = Integer.parseInt(tokens[2].trim());
                    String threadName = tokens[3].trim();
                    for (ProfileAnalyzeTimeRange range : timeRanges) {
                        if (range.isWithinTimeRange(startTime, endTime)) {
                            threadSnapshots.add(new ThreadSnapshot(startTime, endTime, threadId, threadName));
                        }
                    }
                } else {
                    System.out.println("Invalid format for line: " + line);
                }
            }
        }
    }
    return threadSnapshots;
}
